func lsfToNativeListHeader(x *lsfList[*lsfHeader]) []Header {
	out := make([]Header, 0, x.length())
	for c := x; c != nil; c = c.tail {
		out = append(out, lsfToNativeHeader(c.head))
	}
	return out
}

func lsfToNativeMaybeLastSend(x lsfMaybe[*lsfLastSend]) LawSpecMaybe[LastSend] {
	if x.ok {
		return LawSpecPresent[LastSend](lsfToNativeLastSend(x.v))
	}
	return LawSpecAbsent[LastSend]()
}

