func lsfToNativeKafkaError(x lsfKafkaError) KafkaError {
	switch x {
	case lsfKafkaError_UnknownTopicOrPartition:
		return KafkaErrorUnknownTopicOrPartition{}
	case lsfKafkaError_TopicAlreadyExists:
		return KafkaErrorTopicAlreadyExists{}
	case lsfKafkaError_InvalidTopic:
		return KafkaErrorInvalidTopic{}
	case lsfKafkaError_InvalidPartitions:
		return KafkaErrorInvalidPartitions{}
	case lsfKafkaError_InvalidRecord:
		return KafkaErrorInvalidRecord{}
	case lsfKafkaError_InvalidRequest:
		return KafkaErrorInvalidRequest{}
	case lsfKafkaError_OffsetOutOfRange:
		return KafkaErrorOffsetOutOfRange{}
	case lsfKafkaError_OutOfOrderSequenceNumber:
		return KafkaErrorOutOfOrderSequenceNumber{}
	case lsfKafkaError_InvalidProducerEpoch:
		return KafkaErrorInvalidProducerEpoch{}
	case lsfKafkaError_ProducerFenced:
		return KafkaErrorProducerFenced{}
	case lsfKafkaError_UnknownProducerId:
		return KafkaErrorUnknownProducerId{}
	case lsfKafkaError_InvalidProducerIdMapping:
		return KafkaErrorInvalidProducerIdMapping{}
	case lsfKafkaError_InvalidTxnState:
		return KafkaErrorInvalidTxnState{}
	case lsfKafkaError_InvalidGroupId:
		return KafkaErrorInvalidGroupId{}
	case lsfKafkaError_UnknownMemberId:
		return KafkaErrorUnknownMemberId{}
	case lsfKafkaError_IllegalGeneration:
		return KafkaErrorIllegalGeneration{}
	case lsfKafkaError_IllegalState:
		return KafkaErrorIllegalState{}
	}
	panic("unreachable branch reached")
}

func lsfToNativeLogEntry(x lsfLogEntry) LogEntry {
	switch y := x.(type) {
	case *lsfLogEntry_DataEntry:
		return LogEntryDataEntry{lsfToNativeDataEntryDetails(y.fValue)}
	case *lsfLogEntry_ControlEntry:
		return LogEntryControlEntry{lsfToNativeControlEntryDetails(y.fValue)}
	}
	panic("unreachable branch reached")
}

