func lsfEqualBytes(a, b string) bool {
	return a == b
}

func lsfEqualHeader(a, b *lsfHeader) bool {
	if a == b {
		return true
	}
	return true && a.fName == b.fName && lsfEqualMaybeBytes(a.fContent, b.fContent)
}
